#!/usr/bin/env node
//
// THE RUNNER FOR EVERY TOOL TEST, because neither shorter spelling holds across the matrix.
//
// `node --test "./tools/**/*.test.js"` leaves the glob to Node, and Node 20 cannot expand one —
// it answers `Could not find './tools/**/*.test.js'`. `node --test ./tools` reads the directory as
// a single test FILE and dies loading it, `MODULE_NOT_FOUND`, on every version in the matrix. The
// shell cannot expand it either: npm runs scripts under `sh` on Linux and macOS and `cmd.exe` on
// Windows, and `**` means nothing to either.
//
// So the file list gets ENUMERATED HERE and handed to Node as plain arguments, which every version
// accepts. `execFileSync` without a shell passes them as an argument vector, so a hundred paths
// never reach cmd.exe's command-line ceiling the way a joined string would.
'use strict';

const path = require('node:path');
const { execFileSync } = require('node:child_process');
const { walkMatching } = require('./walk.js');

const ROOT = path.resolve(__dirname, '..');
const tests = walkMatching(__dirname, (name) => name.endsWith('.test.js'))
  .map((f) => path.relative(ROOT, f));

if (!tests.length) {
  // A RUN THAT FINDS NOTHING READS AS A PASS, and a green with no tests behind it is the one
  // reading this script exists to refuse.
  console.error('tool-test-run  no tool test stands under tools/, so this run would prove nothing');
  process.exit(1);
}

const argv = process.argv.slice(2);
try {
  execFileSync(process.execPath, ['--test', '--test-concurrency=4', ...argv, ...tests],
    { cwd: ROOT, stdio: 'inherit' });
} catch (e) {
  process.exit(e.status ?? 1);
}

