34	    { encoding: 'utf8', cwd: ROOT }).trim().split('\n').filter(Boolean);
35	  return cached;
36	}
37	
38	/**
39	 * Write a snapshot beside each file, under one scope.
40	 *
41	 * @param {string} scope  the grammar a file opens under
42	 * @param {string[]} files  paths to tokenize
43	 * @param {{extra?: string[], quiet?: boolean}} [options]  extra grammars, and whether to swallow output
44	 */
45	function snapshot(scope, files, options = {}) {
46	  if (!files.length) return;
47	  snapRun([...grammarArgs(), ...(options.extra ?? []), '-s', scope, '-u'], files,
48	    { stdio: options.quiet === false ? 'inherit' : 'ignore' });
49	}
50	
51	// ── the same grammars, read in this process ───────────────────────────────────────────────────
52	//
53	// The snapshotter spawns a process, writes a file and reads it back. A sweep asking one question
54	// of several hundred specimens pays that cost several hundred times, which puts a whole class of
55	// instrument out of reach — anything that probes real text at every position rather than a table
56	// of examples.
57	//
58	// vscode-tmgrammar-test carries the registry the snapshotter itself builds, so loading it here
59	// reads the same grammars under the same injections. Collided against every pinned snapshot in
60	// tests/samples: 31 of 31 reproduce scope for scope.
61	
62	let registry = null;
63	const loaded = new Map();
64	
65	/** The registry the snapshotter builds: the manifest's grammars, plus the extras grammars.sh names. */
66	function grammarRegistry() {
67	  if (registry) return registry;
68	  const { createRegistry } = require('vscode-tmgrammar-test/dist/common/index.js');
69	  const fs = require('node:fs');
70	  const manifest = require(path.join(ROOT, 'package.json')).contributes || {};
71	  const seen = new Set();
72	  const grammars = [];
73	  for (const g of manifest.grammars || []) {
74	    const file = path.resolve(ROOT, g.path);
75	    if (!fs.existsSync(file)) continue;
76	    seen.add(file);
77	    grammars.push({ path: file, scopeName: g.scopeName, injectTo: g.injectTo });
78	  }
79	  const args = grammarArgs();
80	  for (let i = 0; i < args.length; i += 1) {
81	    if (args[i] !== '-g') continue;
82	    const file = path.resolve(ROOT, args[i + 1]);
83	    if (seen.has(file) || !fs.existsSync(file)) continue;
84	    seen.add(file);
85	    grammars.push({ path: file });
86	  }
87	  registry = createRegistry(grammars);
88	  return registry;
89	}
90	
91	/**
92	 * Every token a scope's grammar names in a text, line by line.
93	 *
94	 * A grammar this registry cannot resolve — one of the several dozen VS Code ships that a bare
95	 * checkout carries none of — warns on stderr and drops out of the reading, the same way it does
96	 * under the snapshotter.
97	 *
98	 * @param {string} scope  the grammar the text opens under
99	 * @param {string} text
100	 * @returns {Promise<Array<Array<{startIndex:number,endIndex:number,scopes:string[]}>>>}
101	 */
102	async function tokenize(scope, text) {
103	  return (await tokenizeFrom(scope, text.split('\n'))).tokens;
104	}
105	
106	/**
107	 * The same reading, handing back the RULE STACK each line ends on.
108	 *
109	 * A grammar reads strictly left to right, so the stack a line ends on depends on the lines before
110	 * it and on nothing after. A caller asking one question of a text at every cut can therefore read
111	 * the text ONCE and resume from the stack a cut ends on, where re-reading the whole prefix at every
112	 * cut costs the square of the file's length. `still --reach` reads 4403 carriers that way.
113	 *
114	 * @param {string} scope  the grammar the lines open under
115	 * @param {string[]} lines  the lines, without their newlines
116	 * @param {unknown} [stack]  the stack to resume from, or nothing to open fresh
117	 * @returns {Promise<{tokens: Array<Array<{startIndex:number,endIndex:number,scopes:string[]}>>, stacks: unknown[]}>}
118	 */
119	async function tokenizeFrom(scope, lines, stack = null) {
120	  if (!loaded.has(scope)) loaded.set(scope, await grammarRegistry().loadGrammar(scope));
121	  const grammar = loaded.get(scope);
122	  if (!grammar) throw new Error(`no grammar stands under ${scope}`);
123	  const tokens = [];
124	  const stacks = [];
125	  for (const line of lines) {
126	    const read = grammar.tokenizeLine(line, stack);
127	    stack = read.ruleStack;
128	    tokens.push(read.tokens);
129	    stacks.push(stack);
130	  }
131	  return { tokens, stacks };
132	}
133	
134	/**
135	 * The scopes a word carries, wherever a token's own text equals it exactly — joined as one string,
136	 * or `null` if no token matches. Two invariants read this identically (an attribute value and an
137	 * image attribute, each written once inline and once spanning a line break); one body here answers
138	 * both rather than carrying the same walk twice.
139	 *
140	 * @param {string} scope  the grammar the text opens under
141	 * @param {string} text
142	 * @param {string} word  the exact token text to find
143	 * @returns {Promise<string|null>}
144	 */
145	async function scopesOn(scope, text, word) {
146	  const lines = await tokenize(scope, text);
147	  const rows = text.split('\n');
148	  for (let row = 0; row < lines.length; row += 1) {
149	    for (const token of lines[row]) {
150	      if ((rows[row] ?? '').slice(token.startIndex, token.endIndex).trim() === word) {
151	        return token.scopes.join(' ');
152	      }
153	    }
154	  }
155	  return null;
156	}
157	
158	module.exports = { ROOT, grammarArgs, grammarRegistry, snapshot, tokenize, tokenizeFrom, scopesOn };
