input.command:
cat >> tools/invariants/ships-no-runtime.test.js <<'JS'

// ── THE SURFACE IS BOUNDED, NOT ONLY POPULATED ────────────────────────────────────────────────
//
// Every reading above asks whether what the manifest PROMISES reaches the package. None asks the
// other direction, and the gate that builds a real .vsix — `tools/package-contents.js` — asked only
// the same way. So the package's size was never anybody's measurement: a directory the ignore list
// does not name ships whatever it holds, and the only thing standing between a user and this
// repository's 128 MB of agent worktree was that nobody had run `vsce` on a machine that had one.
//
// So the surface derives on BOTH sides. What the manifest registers packs, and what packs is either
// something the manifest registers or one of the few files named here, each because a user or a
// theme author opens it. A file matching neither is a LEAK, and it reads as one.
const SHIPPED = new Map([
  ['package.json', 'the manifest VS Code reads to register everything else'],
  ['README.md', 'what the extension is, which the Marketplace renders'],
  ['CHANGELOG.md', 'what moved between versions, which the Marketplace renders'],
  ['LICENSE', 'the terms the package ships under'],
  ['ThirdPartyNotices.txt', 'the terms the vendored grammars ship under'],
  ['MIGRATION.md', 'the scope renames a theme written against an older version must follow'],
  ['SCOPE-NAMES.md', 'the scope vocabulary a theme author writes rules against'],
  ['contributing.md', 'where a reader who wants to change the grammar goes next'],
  ['tw5.png', 'the icon the manifest names']
]);

/**
 * Packed paths that neither the manifest registers nor `SHIPPED` names.
 *
 * Exported shape kept pure so a collision can plant a listing: the live reading below cannot stage
 * a leak without writing one into this repository, and a gate that can only be collided by dirtying
 * the tree it measures does not get collided.
 *
 * @param {string[]} packed  paths as `vsce ls` prints them, repository-relative
 * @param {object} manifest  a package.json shape
 * @returns {string[]} the strays, sorted
 */
function strayFiles(packed, manifest) {
  const c = manifest.contributes ?? {};
  const registered = new Set([
    ...(c.grammars ?? []).map((g) => g.path),
    ...(c.snippets ?? []).map((s) => s.path),
    ...(c.languages ?? []).filter((l) => l.configuration).map((l) => l.configuration),
    manifest.icon,
    manifest.main
  ].filter(Boolean).map((p) => p.replace(/^\.\//, '')));
  return packed.filter((f) => !registered.has(f) && !SHIPPED.has(f)).sort();
}

test('nothing packs that the manifest does not register and this file does not name', { timeout: 120000 }, (t) => {
  const packed = packedFiles();
  if (!packed) {
    t.skip('no `vsce` stands here — the ignore list stands unread');
    return;
  }
  assert.deepStrictEqual(strayFiles(packed, pkg), [],
    'file(s) pack that nothing accounts for — name them in SHIPPED or exclude them in .vscodeignore');
});

// THE COLLISION. A planted listing carries the two shapes this repository really grows — a harness
// file and an agent worktree — and both must read as strays, or the check above rests on a tree that
// happens to be clean today.
test('a harness file and an agent worktree both read as strays', () => {
  const planted = [
    'package.json',
    'syntaxes/tiddlywiki5.json',
    'corpus/memetic/control-set.mem',
    '.claude/worktrees/spirit/tools/theme-model.js',
    'themes/gruvbox/gruvbox-dark-hard.json'
  ];
  assert.deepStrictEqual(strayFiles(planted, pkg), [
    '.claude/worktrees/spirit/tools/theme-model.js',
    'corpus/memetic/control-set.mem',
    'themes/gruvbox/gruvbox-dark-hard.json'
  ], 'the reading let a harness file or a worktree through');
});

// A SHIPPED NAME THAT PACKS NOTHING IS A RULING ABOUT A FILE THAT LEFT. It reads as stale here
// rather than standing forever as permission nobody uses.
test('every name this file ships stands in the tree', () => {
  for (const [file, why] of SHIPPED) {
    assert.ok(fs.existsSync(path.join(ROOT, file)),
      `SHIPPED names \`${file}\` — ${why} — and no such file stands here`);
  }
});
JS
timeout 600 node --test --test-reporter=tap tools/invariants/ships-no-runtime.test.js 2>&1 | grep -E "^(not ok|ok|# (pass|fail))" | cut -c1-150

