    "autoCloseBefore": ";:.,=}])> \n\t",
    "surroundingPairs": [
        ["<%", "%>"],
        ["<<", ">>"],
        ["[[", "]]"],
        ["{", "}"],
        ["[", "]"],
        ["(", ")"],
        ["\"", "\""],
        ["'", "'"],
        ["`", "`"]
