node -e "const l=require('./package.json').contributes.languages.find(x=>x.id==='memetic-wikitext'); console.log('valid JSON; firstLine:', l.firstLine)" && git diff --stat package.json && python3 - <<'PY'
p='tools/invariants/language-selection.test.js'; s=open(p,encoding='utf-8').read()

# the two corpus-derived readings become pure over a pattern, so a collision plants one in-process
a = """const memetic = languageOf('memetic-wikitext');
"""
b = """const memetic = languageOf('memetic-wikitext');

/**
 * The corpus split by whether a specimen's first line DECLARES a carrier, read the way the grammar
 * names the declaring forms rather than by asking the pattern under test.
 *
 * @returns {{declaring: {file:string,line:string}[], silent: {file:string,line:string}[]}}
 */
function split() {
  const declaring = [];
  const silent = [];
  for (const file of specimensFor(memetic.extensions)) {
    const line = firstLineOf(file);
