node -e "
const fs=require('fs');
const {parseJsonc}=require('./tools/jsonc.js');
const files=['language-configuration.json','syntaxes/tw5-test-file.json','syntaxes/tw5-tid-file.json','.vscode/launch.json'];
for(const p of files){
  const before=fs.readFileSync(p,'utf8');
  const dataBefore=JSON.stringify(parseJsonc(before));
  const lines=before.split('\n');
  const after=lines.map(l=>{ const m=/^\t+/.exec(l); return m? '    '.repeat(m[0].length)+l.slice(m[0].length) : l; });
  const text=after.join('\n');
  if(JSON.stringify(parseJsonc(text))!==dataBefore) throw new Error('parse moved: '+p);
  const a=lines.map(l=>l.replace(/^[\t ]+/,'')), b=after.map(l=>l.replace(/^ +/,''));
  if(a.join('\n')!==b.join('\n')) throw new Error('content moved: '+p);
  fs.writeFileSync(p,text);
  console.log(p+': '+lines.filter(l=>l.startsWith('\t')).length+' tab-indented line(s) -> 4 spaces, parse identical');
}
" && echo "=== leading tabs left in our own files ===" && git ls-files '*.json' | grep -vE "^tests/grammars/|^syntaxes/attic/" | while read f; do n=$(grep -cP '^\t' "$f" 2>/dev/null); [ "$n" != "0" ] && echo "  $n  $f"; done; echo "(nothing listed = clean)"

