const fs=require('fs'),os=require('os'),path=require('path');
const {snapshot}=require('./tools/tokenizer.js');
const D='text/memetic-wikitext+tiddlywiki', SIGIL='<<~ stance \"poet\">>';
const cases={
  'type FIRST, title after':    ['type: '+D,'title: Probe','',SIGIL,''],
  'type LAST in the header':    ['title: Probe','caption: Cap','type: '+D,'',SIGIL,''],
  'type MIDDLE':                ['title: Probe','type: '+D,'caption: Cap','',SIGIL,''],
  'type with padded colon':     ['title: Probe','type : '+D,'',SIGIL,''],
  'type with leading space':    ['title: Probe',' type: '+D,'',SIGIL,''],
  'type with trailing space':   ['title: Probe','type: '+D+' ','',SIGIL,'']
};
const d=fs.mkdtempSync(path.join(os.tmpdir(),'tid-order-'));
const files=[]; const names=[];
let i=0;
for(const [name,lines] of Object.entries(cases)){ const f=path.join(d,'p'+(i++)+'.tid'); fs.writeFileSync(f,lines.join('\n')); files.push(f); names.push(name); }
snapshot('source.tiddlywiki5.tid-file',files);
files.forEach((f,n)=>{
  const snap=fs.readFileSync(f+'.snap','utf8');
  let inLine=false; const carried=new Set();
  for(const line of snap.split('\n')){
    if(line.startsWith('>')){ inLine=line.slice(1).trim()===SIGIL; continue; }
    if(!inLine) continue;
    const m=/^#\s*\^+ (.*)\$/.exec(line); if(m) m[1].split(/\s+/).forEach(s=>s&&carried.add(s));
  }
  const dialect=[...carried].some(s=>s.endsWith('.memetic-wikitext'));
  console.log((dialect?'  DIALECT  ':'  plain    ')+names[n]);
});
fs.rmSync(d,{recursive:true,force:true});
